package com.oms.order.service;
import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;
/** A frozen whole-kit return scope expands to source-specific plans; receipt posting remains per physical SKU. */
@Service public class RefundBundleReturns {
 @Resource RefundService refunds;
 @Resource RefundGoodsService goods;
 private OrderRepository r(){return refunds.repository;}
 public Map<String,Object> create(String c,long id,Map<String,Object> input,String actor){return createFenced(c,id,input,actor,null);}
 @SuppressWarnings("unchecked") Map<String,Object> createFenced(String c,long id,Map<String,Object> input,String actor,Runnable fence){
  Map<String,Object> hint=refunds.business(c,id,false);long bundle=number(input,"bundle_id"),units=number(input,"quantity");require(Boolean.TRUE.equals(input.get("confirmed"))&&units>0,"请确认整套退回范围和套数");
  Map<String,Object> intent=refunds.tx().execute(tx->{Map<String,Object> b=refunds.business(c,id,true);if(fence!=null)fence.run();require(number(b,"control_version")==number(input,"control_version"),"退款单已变化，请刷新");require("APPROVED".equals(text(b,"review_state"))&&!"DONE".equals(text(b,"goods_state")),"请审核退回方案，已结案退款不能创建退回");Map<String,Object> platform=refunds.platform(c,number(b,"platform_refund_id"),true);require(number(b,"approved_version")==number(platform,"version")&&"VALID".equals(text(platform,"source_state"))&&!"CLOSED".equals(text(platform,"platform_status")),"请审核当前有效平台版本");require(Arrays.asList("RETURN","REFUSAL","INTERCEPT").contains(text(b,"goods_action")),"当前货物方案不需要退回");
   List<Map<String,Object>> parent=r().db().query("SELECT * FROM oms_order_bundle WHERE company_code=? AND order_id=? AND platform_oid=? AND id=?",ROW,c,b.get("order_id"),b.get("platform_oid"),bundle);require(parent.size()==1&&units<=number(parent.get(0),"quantity"),"套装不属于本退款子单或退回套数超出购买数量");
   List<Map<String,Object>> old=r().db().query("SELECT request_json,quantity FROM oms_refund_bundle_return WHERE company_code=? AND refund_id=? AND bundle_id=? FOR UPDATE",ROW,c,id,bundle);if(!old.isEmpty()){Map<String,Object> frozen=obj(old.get(0).get("request_json"));require(number(old.get(0),"quantity")==units,"已有整套退回范围，不能覆盖套数");if("LUCKY_BAG".equals(text(parent.get(0),"business_type"))&&!RefundLuckyReturns.unitIds(input).isEmpty())require(RefundLuckyReturns.unitIds(input).equals(RefundLuckyReturns.unitIds(frozen)),"已有整袋退回范围，不能换成其他原袋");for(String field:Arrays.asList("store_code","return_address","return_contact"))require(text(input,field).equals(text(frozen,field)),"请沿用原整套安排的仓库和地址，变更请在原计划处理");return frozen;}
   String store=required(input,"store_code",64),address=required(input,"return_address",500),contact=required(input,"return_contact",200),reason=required(input,"reason",500),evidence=required(input,"evidence",1000);List<Map<String,Object>> requests=new ArrayList<>();
   List<Map<String,Object>> children=r().db().query("SELECT * FROM oms_order_line WHERE company_code=? AND order_id=? AND bundle_id=? ORDER BY id FOR UPDATE",ROW,c,b.get("order_id"),bundle);require(!children.isEmpty()&&children.size()<=500,"原销售组合组成明细缺失");
   if("LUCKY_BAG".equals(text(parent.get(0),"business_type")))requests.addAll(RefundLuckyReturns.requests(r(),c,b,parent.get(0),input));else for(Map<String,Object> child:children){long left=Math.multiplyExact(units,number(child,"component_quantity"));require(number(child,"component_quantity")>0&&left<=100000000,"组件退回数量无效");for(Map<String,Object> source:r().db().query("SELECT l.*,s.shipment_sn FROM oms_order_shipment_line l JOIN oms_order_shipment s ON s.company_code=l.company_code AND s.id=l.shipment_id WHERE l.company_code=? AND l.order_line_id=? AND l.shipped_quantity>0 ORDER BY l.id FOR UPDATE",ROW,c,child.get("id"))){require(r().db().queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? AND shipment_line_id=?",Long.class,c,id,source.get("id"))==0,"本退款已有组件安排，请按指定组件处理，不重复创建整套范围");long capacity=number(source,"shipped_quantity")-ReturnSourceClaims.refundUsed(r(),c,number(source,"id"),0,id)-ReturnSourceClaims.exchangeUsed(r(),c,number(source,"id")),take=Math.min(left,Math.max(0,capacity));if(take>0){requests.add(m("shipment_line_id",source.get("id"),"sku_sn",source.get("sku_sn"),"goods_name",source.get("goods_name"),"quantity",take,"request_key","KB"+id+"_"+bundle+"_"+source.get("id")));left-=take;}if(left==0)break;}require(left==0,"组件 "+child.get("sku_sn")+" 的可退实发数量不足，不能按整套安排；可选择指定组件退回");}
   Map<String,Object> frozen=m("bundle_id",bundle,"quantity",units,"store_code",store,"return_address",address,"return_contact",contact,"reason",reason,"evidence",evidence,"requests",requests,"business_type",parent.get(0).get("business_type"),"unit_ids",input.getOrDefault("unit_ids",Collections.emptyList()));r().insert("INSERT INTO oms_refund_bundle_return(company_code,refund_id,bundle_id,quantity,request_json,actor) VALUES (?,?,?,?,?,?)",c,id,bundle,units,encode(frozen),actor);for(Map<String,Object> request:requests)r().db().update("INSERT INTO oms_refund_bundle_claim(company_code,refund_id,bundle_id,shipment_line_id,quantity) VALUES (?,?,?,?,?)",c,id,bundle,request.get("shipment_line_id"),request.get("quantity"));refunds.event(c,id,"BUNDLE_RETURN","固定原销售组合退回范围："+parent.get(0).get("sku_sn")+" × "+units+("LUCKY_BAG".equals(text(parent.get(0),"business_type"))?" 袋":" 套")+"，按原实际发货明细安排组件，库存仅在实收后入账",actor);return frozen;
  });
  for(Map<String,Object> source:(List<Map<String,Object>>)intent.get("requests")){Map<String,Object> body=new LinkedHashMap<>(intent);body.putAll(source);body.put("confirmed",true);body.put("control_version",refunds.business(c,id,false).get("control_version"));goods.create(c,id,body,actor);}
  return goods.report(c,id);
 }
 @SuppressWarnings("unchecked") static void guardSource(OrderRepository r,String c,long refund,long shipment,long quantity,String store,String address,String contact){for(Map<String,Object> row:r.db().query("SELECT br.request_json FROM oms_refund_bundle_return br JOIN oms_order_shipment_line sl ON sl.company_code=br.company_code AND sl.id=? JOIN oms_order_line ol ON ol.company_code=sl.company_code AND ol.id=sl.order_line_id AND ol.bundle_id=br.bundle_id WHERE br.company_code=? AND br.refund_id=?",ROW,shipment,c,refund)){Map<String,Object> frozen=obj(row.get("request_json"));boolean matched=false;for(Map<String,Object> request:(List<Map<String,Object>>)frozen.get("requests"))if(number(request,"shipment_line_id")==shipment&&number(request,"quantity")==quantity)matched=true;require(matched&&store.equals(text(frozen,"store_code"))&&address.equals(text(frozen,"return_address"))&&contact.equals(text(frozen,"return_contact")),"整套退回范围已固定，请沿用原组件数量和退回仓");}}
 @SuppressWarnings("unchecked") static void guardComplete(OrderRepository r,String c,long refund){for(Map<String,Object> row:r.db().query("SELECT request_json FROM oms_refund_bundle_return WHERE company_code=? AND refund_id=?",ROW,c,refund))for(Map<String,Object> request:(List<Map<String,Object>>)obj(row.get("request_json")).get("requests")){List<Map<String,Object>> plans=r.db().query("SELECT quantity FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? AND shipment_line_id=?",ROW,c,refund,request.get("shipment_line_id"));require(plans.size()==1&&number(plans.get(0),"quantity")==number(request,"quantity"),"整套退回组件尚未全部建立安排，请继续原整套退回流程");}}
 @SuppressWarnings("unchecked") static List<Map<String,Object>> report(OrderRepository r,String c,long refund){List<Map<String,Object>> heads=r.db().query("SELECT br.*,b.sku_sn,b.goods_name,b.business_type FROM oms_refund_bundle_return br JOIN oms_order_bundle b ON b.company_code=br.company_code AND b.id=br.bundle_id WHERE br.company_code=? AND br.refund_id=? ORDER BY br.id",ROW,c,refund);for(Map<String,Object> head:heads){List<Map<String,Object>> rows=new ArrayList<>();for(Map<String,Object> request:(List<Map<String,Object>>)obj(head.get("request_json")).get("requests")){Map<String,Object> line=new LinkedHashMap<>(request);List<Map<String,Object>> p=r.db().query("SELECT accepted_quantity,posted_quantity,waived_quantity,state FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? AND shipment_line_id=?",ROW,c,refund,request.get("shipment_line_id"));line.put("accepted_quantity",0);line.put("posted_quantity",0);line.put("waived_quantity",0);line.put("state","NOT_CREATED");if(!p.isEmpty())line.putAll(p.get(0));line.put("remaining",number(line,"quantity")-number(line,"accepted_quantity")-number(line,"waived_quantity"));rows.add(line);}head.put("unit_ids",obj(head.get("request_json")).getOrDefault("unit_ids",Collections.emptyList()));head.remove("request_json");head.put("components",rows);head.put("pending_quantity",rows.stream().mapToLong(l->number(l,"remaining")).sum());}return heads;}
}
